pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    function testFuzz_property(address from, address recipient, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(recipient != address(0));
        Recorder rec = new Recorder();
        address[] memory tos = new address[](1);
        tos[0] = recipient;
        c.transfer(from, address(rec), tos, v);
        (address a0, address a1, uint256 av) = rec.lastTransferFromArgs();
        assertTrue(a0 == from && a1 == recipient && av == v);
    }
}

contract Recorder {
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;
    bool public recorded;

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        recorded = true;
        return true;
    }

    function lastTransferFromArgs() external view returns (address, address, uint256) {
        return (lastFrom, lastTo, lastValue);
    }
}
